return {["fbwp01"]={["canSee"]=1,["dsc"]=[[一尊僧人的雕像。观其貌，老僧已然年逾花甲，却依然精神矍铄。看其神，目蕴慈笑，眼现智珠，暗含得道高僧的气度。]],["id"]=[[fbwp01]],["name"]=[[雕像]]},["fbwp02"]={["canSee"]=1,["dsc"]=[[一尊道士的雕像。道士年过古稀，须发成缕，虽然衣衫不整，不修边幅，抬手间，却有一派仙风道骨之姿。]],["id"]=[[fbwp02]],["name"]=[[雕像]]},["fbwp03"]={["canSee"]=1,["dsc"]=[[一尊女子的雕像。女子看起来正值二八年华，原本是天生丽质，国色天香的佳人，却有一对傲气十足的剑眉。执剑指苍穹，似是天塌地陷也绝不肯屈服。]],["id"]=[[fbwp03]],["name"]=[[雕像]]}}000000000000